)


class ModelNew(nn.Module):
    """
    Optimized FP8 Matrix Multiplication using fused HIP kernels.

    Key optimizations:
    1. Fused quantization + matmul in single kernel (reduces memory traffic)
    2. Shared memory tiling for efficient GEMM
    3. Parallel reduction for amax computation
    4. Optimized for FP32 precision as specified
    """

    def __init__(self, M: int, K: int, N: int, use_e4m3: bool = True):
        super().__init__()
        self.M = M
        self.K = K
        self.N = N
        self.use_e4m3 = use_e4m3

        # Use our custom kernels
        self.compute_amax = optimized_fp8_matmul.compute_amax_hip
        self.fused_quantize_matmul = optimized_fp8_matmul.fused_quantize_matmul_hip

        # FP8 format specifications
        if use_e4m3:
            self.fp8_dtype = torch.float8_e4m3fn
            self.fp8_max = 448.0  # Max representable value in E4M3
        else:
            self.fp8_dtype = torch.float8_e5m2
            self.fp8_max = 57344.0  # Max representable value in E5M2

        # Weight matrix
        self.weight = nn.Parameter(torch.randn(K, N) * 0.02)

    def compute_scale(self, x: torch.Tensor) -> torch.Tensor:
        """Compute per-tensor scale for FP8 quantization using optimized kernel."""
        # Use HIP amax kernel
        amax = self.compute_amax(x)
        scale = self.fp8_max / amax.clamp(min=1e-12)
        return scale

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Optimized FP8 matmul using fused quantization + matmul kernel.

        Input x: (batch, seq_len, K) 
        Weight: (K, N)
        Output: (batch, seq_len, N)
        """
        input_dtype = x.dtype
        batch_size = x.shape[0]
        seq_len = x.shape[1]

        # Convert to float32 for precision
        x_2d = x.view(-1, self.K).float()
        w = self.weight.float()

        M_total = x_2d.shape[0]  # batch_size * seq_len

        # Compute scales using optimized amax kernel
        x_scale = self.compute_scale(x_2d)
        w_scale = self.compute_scale(w)

        # Use fused quantize+matmul kernel
        out = self.fused_quantize_matmul(
            x_2d,
            w,
            x_scale.item(),
            w_scale.item(),
            self.fp8_max,
            M_total,
            self.K,
            self.N
        )

        return out.view(batch_size, seq_len, self.N).to(input_dtype)

