optimized_matmul_cpp_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

#define TILE_M 32
#define TILE_N 32
#define TILE_K 16

// Fused compute: element-wise absolute, reduction to find max, and scale computation
__global__ void compute_scale_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    float fp8_max,
    int size
) {
    extern __shared__ float sdata[];

    int idx = threadIdx.x;
    int i = blockIdx.x * blockDim.x * 2 + idx;

    float local_max = 0.0f;

    // Load 2 elements per thread
    if (i < size) {
        float val = fabsf(input[i]);
        local_max = fmaxf(local_max, val);
    }
    if (i + blockDim.x < size) {
        float val = fabsf(input[i + blockDim.x]);
        local_max = fmaxf(local_max, val);
    }

    sdata[idx] = local_max;
    __syncthreads();

    // Reduction in shared memory
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (idx < s) {
            sdata[idx] = fmaxf(sdata[idx], sdata[idx + s]);
        }
        __syncthreads();
    }

    // Write block result
    if (idx == 0) {
        output[blockIdx.x] = sdata[0];
    }
}

// Fused quantized matmul kernel
__global__ void quantized_matmul_kernel(
    const float* __restrict__ a,
    const float* __restrict__ b,
    float* __restrict__ c,
    float scale_a,
    float scale_b,
    float fp8_max,
    int M,
    int K,
    int N
) {
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Compute global indices
    int row_c = by * TILE_M + ty;
    int col_c = bx * TILE_N + tx;

    // Shared memory tiles
    __shared__ float tile_a[TILE_M][TILE_K];
    __shared__ float tile_b[TILE_K][TILE_N];

    float acc = 0.0f;

    int num_tiles = (K + TILE_K - 1) / TILE_K;

    for (int tile = 0; tile < num_tiles; ++tile) {
        // Load A tile with quantization
        int row_a = by * TILE_M + ty;
        int col_a = tile * TILE_K + tx;

        float val_a = 0.0f;
        if (row_a < M && col_a < K) {
            val_a = a[row_a * K + col_a];
            // Simulate FP8 quantization: clamp and scale
            val_a = fminf(fmaxf(val_a * scale_a, -fp8_max), fp8_max);
        }
        tile_a[ty][tx] = val_a;

        // Load B tile with quantization  
        int row_b = tile * TILE_K + ty;
        int col_b = bx * TILE_N + tx;

        float val_b = 0.0f;
        if (row_b < K && col_b < N) {
            val_b = b[row_b * N + col_b];
            // Simulate FP8 quantization: clamp and scale
            val_b = fminf(fmaxf(val_b * scale_b, -fp8_max), fp8_max);
        }
        tile_b[ty][tx] = val_b;

        __syncthreads();

        // Matrix multiplication
        #pragma unroll
        for (int k = 0; k < TILE_K; ++k) {
            acc += tile_a[ty][k] * tile_b[k][tx];
        }

        __syncthreads();
    }

    // Dequantize: multiply by inverse scales
    float scale_inv_a = 1.0f / scale_a;
    float scale_inv_b = 1.0f / scale_b;
    acc *= scale_inv_a * scale_inv_b;

    // Store result
    if (row_c < M && col_c < N) {
        c[row_c * N + col_c] = acc;
    }
}

torch::Tensor compute_scale_hip(torch::Tensor input, float fp8_max) {
    int size = input.numel();
    int block_size = 256;
    int num_blocks = (size + block_size * 2 - 1) / (block_size * 2);

    auto partial_max = torch::zeros(num_blocks, input.options());

    compute_scale_kernel<<<num_blocks, block_size, block_size * sizeof(float)>>>(
        input.data_ptr<float>(),
        partial_max.data_ptr<float>(),
        fp8_max,
        size
    );

    // Final reduction to get single scale value
    float max_val = partial_max.max().item<float>();
    float scale = fp8_max / (max_val < 1e-12f ? 1e-12f : max_val);

    return torch::tensor(scale, input.options());
}

torch::Tensor quantized_matmul_hip(
    torch::Tensor a,
    torch::Tensor b,
    torch::Tensor scale_a,
    torch::Tensor scale_b,
    float fp8_max,
    int M,
    int K,
    int N
) {
    auto c = torch::zeros({M, N}, a.options());

    dim3 block(TILE_N, TILE_M);
    dim3 grid((N + TILE_N - 1) / TILE_N, (M + TILE_M - 1) / TILE_M);

    quantized_matmul_kernel<<<grid, block>>>(
        a.data_ptr<float>(),
        b.data_ptr<float>(),
        c.data_ptr<float>(),
        scale_a.item<float>(),
        scale_b.item<float>(),
        fp8_max,
        M, K, N
    );

    return c;
}
